// Clean-room exhaustive solver for bounded weighted popular matchings.
const N:usize=4;const F:usize=6;
fn decode(mut code:usize,n:usize,m:usize,a:&mut[usize;N])->bool{let mut used=0u32;for i in 0..n{let digit=code%(m+1);code/=m+1;a[i]=digit;if digit>0{let bit=1u32<<(digit-1);if used&bit!=0{return false}used|=bit}}true}
fn lexless(a:&[usize;N],b:&[usize;N],n:usize)->bool{for i in 0..n{if a[i]!=b[i]{return a[i]<b[i]}}false}
fn put(out:*mut u8,at:usize,x:i64){let bytes=x.to_le_bytes();unsafe{std::ptr::copy_nonoverlapping(bytes.as_ptr(),out.add(at),8)}}
#[no_mangle]
pub unsafe extern "C" fn weighted_popular_matching(v:*const i64,length:usize,out:*mut u8,capacity:usize)->i64{if v.is_null()||length<4||length>22||*v<1||*v>4||*v.add(1)<1||*v.add(1)>4{return -1}let n=*v as usize;let m=*v.add(1)as usize;if length!=2+n+n*m{return -1}for i in 0..n{let w=*v.add(2+i);if !(1..=1000).contains(&w){return -1}let mut seen=0u32;for j in 0..m{let rank=*v.add(2+n+i*m+j);if rank<0||rank>=m as i64||seen&(1u32<<rank)!=0{return -1}seen|=1u32<<rank}}
 let total=(m+1).pow(n as u32);let mut best_card=-1i64;let mut best=[usize::MAX;N];for code in 0..total{let mut candidate=[0usize;N];if !decode(code,n,m,&mut candidate){continue}let mut popular=true;for other_code in 0..total{let mut other=[0usize;N];if !decode(other_code,n,m,&mut other){continue}let mut score=0i64;for i in 0..n{let rank_c=if candidate[i]==0{m as i64}else{*v.add(2+n+i*m+candidate[i]-1)};let rank_o=if other[i]==0{m as i64}else{*v.add(2+n+i*m+other[i]-1)};if rank_o<rank_c{score+=*v.add(2+i)}else if rank_o>rank_c{score-=*v.add(2+i)}}if score>0{popular=false;break}}if popular{let card=candidate[..n].iter().filter(|&&x|x>0).count()as i64;if card>best_card||(card==best_card&&lexless(&candidate,&best,n)){best_card=card;best=candidate}}}
 let mut fields=[0i64;F];fields[0]=if best_card<0{0}else{1};fields[1]=best_card.max(0);for i in 0..n{fields[2+i]=if best_card<0{-1}else{best[i]as i64-1}}let bytes=8*(n+2);if out.is_null()||capacity<bytes{return -2}for i in 0..n+2{put(out,8*i,fields[i])}bytes as i64}
